281	def _blocked_cholesky(data: torch.Tensor) -> torch.Tensor:
282	    """Right-looking blocked Cholesky with FP16 tensor-core updates."""
283	    out = data.clone()
284	    n = out.shape[-1]
285	    if out.shape[0] == 1:
286	        block = 4096
287	    elif n == 1024:
288	        block = 256
289	    else:
