291	
292	    # Panel factors and triangular solves keep FP32 tensors.  Level-3 updates
293	    # use FP16 operands with FP32 accumulation.
294	    old_tf32 = torch.backends.cuda.matmul.allow_tf32
295	    try:
296	        # Scope the fast FP32 library policy to this call; do not perturb the
297	        # harness's later input generation or reconstruction matmuls.
298	        torch.backends.cuda.matmul.allow_tf32 = True
299	        for k in range(0, n, block):
